def solve_langford(n):
    """Solve Langford sequence L(2,n) using backtracking."""
    length = 2 * n
    seq = [0] * length

    def backtrack(pos):
        if pos == length:
            return True

        if seq[pos] != 0:
            return backtrack(pos + 1)

        # Try each value from n down to 1
        for v in range(n, 0, -1):
            # Check if v is already placed twice
            count = seq.count(v)
            if count == 2:
                continue

            if count == 0:
                # First occurrence of v
                # Second occurrence should be at pos + v + 1
                second_pos = pos + v + 1
                if second_pos < length and seq[second_pos] == 0:
                    seq[pos] = v
                    seq[second_pos] = v
                    if backtrack(pos + 1):
                        return True
                    seq[pos] = 0
                    seq[second_pos] = 0
            else:
                # This shouldn't happen in our approach since we place both at once
                pass

        return False

    if backtrack(0):
        return seq
    return None

