# Let's also double-check with a more thorough search using pysat
try:
    from pysat.solvers import Glucose3

    n = 6
    length = 12

    # Variables: x[v][i] = True if value v is placed at position i
    # v in 1..6, i in 0..11

    solver = Glucose3()

    # For each value v, exactly 2 positions must be selected, at distance v+1
    for v in range(1, n+1):
        # Possible placements: (i, i+v+1) for valid i
        possible = []
        for i in range(length - v - 1):
            possible.append((i, i + v + 1))

        # Exactly one placement must be chosen
        # Create a variable for each possible placement
        vars_for_v = []
        for idx, (p1, p2) in enumerate(possible):
            var = v * 100 + idx  # unique variable
            vars_for_v.append(var)

        # At least one placement
        solver.add_clause(vars_for_v)

        # At most one placement (pairwise)
        for i in range(len(vars_for_v)):
            for j in range(i+1, len(vars_for_v)):
                solver.add_clause([-vars_for_v[i], -vars_for_v[j]])

    # Each position can have at most one value
    for pos in range(length):
        vars_at_pos = []
        for v in range(1, n+1):
            for idx, (p1, p2) in enumerate([(i, i+v+1) for i in range(length-v-1)]):
                if p1 == pos or p2 == pos:
                    vars_at_pos.append(v * 100 + idx)

        # At most one value at this position
        for i in range(len(vars_at_pos)):
            for j in range(i+1, len(vars_at_pos)):
                solver.add_clause([-vars_at_pos[i], -vars_at_pos[j]])

    if solver.solve():
        model = solver.get_model()
        print("SAT! Model:", model)
    else:
        print("UNSATISFIABLE")

    solver.delete()
except ImportError:
